func parseLogfmtLine(line string) map[string]interface{} {
	row := make(map[string]interface{})
	// Simple logfmt parsing
	parts := strings.FieldsFunc(line, func(r rune) bool {
		return r == ' '
	})

	for _, part := range parts {
		if idx := strings.Index(part, "="); idx > 0 {
			key := part[:idx]
			value := part[idx+1:]

			// Remove quotes if present
			if strings.HasPrefix(value, "\"") && strings.HasSuffix(value, "\"") {
				value = value[1 : len(value)-1]
			}

			// Try to parse as number
			if v, err := tryParseValue(value); err == nil {
				row[key] = v
			} else {
				row[key] = value
			}
		}
	}

	return row
}

func tryParseValue(value string) (interface{}, error) {
	// Try boolean
	if value == "true" {
		return true, nil
	}
	if value == "false" {
		return false, nil
	}

	// Try number
	if strings.Contains(value, ".") {
		var f float64
		_, err := fmt.Sscanf(value, "%f", &f)
		if err == nil {
			return f, nil
		}
	} else {
		var i int64
		_, err := fmt.Sscanf(value, "%d", &i)
		if err == nil {
			return i, nil
		}
	}

	return nil, fmt.Errorf("not a special value")
}

