	scanner := bufio.NewScanner(strings.NewReader(content))

	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}
		m := parseLogfmtLine(line)
		rows = append(rows, m)
	}

	return rows, nil
}

func parseLogfmtLine(line string) map[string]interface{} {
	row := make(map[string]interface{})
	// Simple logfmt parsing - find key=value pairs
	i := 0
	for i < len(line) {
		// Skip whitespace
		for i < len(line) && line[i] == ' ' {
			i++
		}
		if i >= len(line) {
			break
		}

		// Find key
		keyStart := i
		for i < len(line) && line[i] != '=' && line[i] != ' ' {
			i++
		}
		if i >= len(line) || line[i] != '=' {
			break
		}
		key := line[keyStart:i]

		// Skip equals
		i++

		// Find value
		var value string
		if i < len(line) && line[i] == '"' {
			// Quoted value
			i++
			valueStart := i
			for i < len(line) && line[i] != '"' {
				i++
			}
			value = line[valueStart:i]
			if i < len(line) {
				i++ // Skip closing quote
			}
		} else {
			// Unquoted value
			valueStart := i
			for i < len(line) && line[i] != ' ' {
				i++
			}
			value = line[valueStart:i]
		}

		// Parse value
		if v, err := tryParseValue(value); err == nil {
			row[key] = v
		} else {
			row[key] = value
		}
	}

	return row
}

func tryParseValue(value string) (interface{}, error) {
	// Try boolean
	if value == "true" {
		return true, nil
	}
	if value == "false" {
		return false, nil
	}

	// Try number
	if strings.Contains(value, ".") {
		var f float64
		_, err := fmt.Sscanf(value, "%f", &f)
		if err == nil {
			return f, nil
		}
	} else {
		var i int64
		_, err := fmt.Sscanf(value, "%d", &i)
		if err == nil {
			return i, nil
		}
	}

	return nil, fmt.Errorf("not a special value")
}
