	interactivePtr := flag.Bool("i", false, "Enter interactive REPL")
	interactiveLongPtr := flag.Bool("interactive", false, "Enter interactive REPL")
	versionPtr := flag.Bool("version", false, "Show version")
	helpPtr := flag.Bool("h", false, "Show help")
	helpLongPtr := flag.Bool("help", false, "Show help")

	flag.Parse()

	if *versionPtr {
		fmt.Printf("dsq %s\n", VERSION)
		return
	}

	if *helpPtr || *helpLongPtr {
		printHelp()
		return
	}

	pretty := *prettyPtr || *prettyLongPtr
	cache := *cachePtr || *cacheLongPtr
	_ = *interactivePtr
	_ = *interactiveLongPtr

