func processData(content string, format string, files []string, query string, schemaOnly bool, cache bool) (interface{}, error) {
	// If we have content, it's from stdin
	if content != "" {
		rows, err := parseContent(content, format)
		if err != nil {
			return nil, err
		}

		if schemaOnly {
			return rows, nil
		}

		if query == "" {
			return rows, nil
		}

		// Execute SQL query
		result, err := executeSQLQuery([]interface{}{rows}, query)
		if err != nil {
			return nil, err
		}
		return result, nil
	}

	// Otherwise, process files
	if len(files) == 0 {
		return nil, fmt.Errorf("no input provided")
	}

	allData := []interface{}{}
	for _, file := range files {
		content, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}

		format := detectFormat(file)
		rows, err := parseContent(string(content), format)
		if err != nil {
			return nil, err
		}
		allData = append(allData, rows)
	}

	if schemaOnly {
		if len(allData) == 1 {
			return allData[0], nil
		}
		return allData, nil
	}

	if query == "" {
		if len(allData) == 1 {
			return allData[0], nil
		}
		return allData, nil
	}

	// Execute SQL query
	result, err := executeSQLQuery(allData, query)
	if err != nil {
		return nil, err
	}
	return result, nil
}

func detectFormat(filename string) string {
	ext := strings.ToLower(filepath.Ext(filename))
	switch ext {
	case ".csv":
		return "csv"
	case ".tsv":
		return "tsv"
	case ".json":
		return "json"
	case ".jsonl", ".ndjson":
		return "ndjson"
	case ".parquet":
		return "parquet"
	case ".xlsx":
		return "xlsx"
	case ".xls":
		return "xls"
	case ".ods":
		return "ods"
	case ".avro":
		return "avro"
	case ".orc":
		return "orc"
	case ".logfmt":
		return "logfmt"
	default:
		return "json"
	}
}

func parseContent(content string, format string) ([]map[string]interface{}, error) {
