package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

func executeSQLQuery(dataArrays []interface{}, query string) (interface{}, error) {
	if query == "" {
		// No query, return all data
		if len(dataArrays) == 1 {
			return dataArrays[0], nil
		}
		return dataArrays, nil
	}

	// Replace {} with {0}
	query = strings.ReplaceAll(query, "{}", "{0}")

	// Parse the query
	parsed, err := parseQuery(query)
	if err != nil {
		return nil, err
	}

	// Get the main data source
	if parsed.FromIdx >= len(dataArrays) {
		return nil, fmt.Errorf("invalid table index")
	}

	data, ok := dataArrays[parsed.FromIdx].([]map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid data format")
	}

	// Apply WHERE filter
	if parsed.Where != "" {
		data = filterRows(data, parsed.Where)
	}

	// Apply SELECT projection
	if len(parsed.Select) > 0 && parsed.Select[0] != "*" {
		data = projectRows(data, parsed.Select)
	}

	// Apply LIMIT
	if parsed.Limit > 0 && len(data) > parsed.Limit {
		data = data[:parsed.Limit]
	}

	return data, nil
}

type Query struct {
	Select  []string
	From    string
	FromIdx int
	Where   string
	Limit   int
	Offset  int
}

func parseQuery(query string) (*Query, error) {
	q := &Query{
		Limit:  -1,
		Offset: 0,
	}

	upperQuery := strings.ToUpper(query)

	// SELECT clause
	selectRe := regexp.MustCompile(`(?i)SELECT\s+(.+?)\s+FROM`)
	selectMatch := selectRe.FindStringSubmatch(query)
	if selectMatch != nil {
		fields := selectMatch[1]
		for _, f := range strings.Split(fields, ",") {
			q.Select = append(q.Select, strings.TrimSpace(f))
		}
	}

	// FROM clause - look for {N} pattern
	fromRe := regexp.MustCompile(`(?i)FROM\s+\{(\d+)\}`)
	fromMatch := fromRe.FindStringSubmatch(query)
	if fromMatch != nil {
		fmt.Sscanf(fromMatch[1], "%d", &q.FromIdx)
		q.From = fmt.Sprintf("t%d", q.FromIdx)
	}

	// WHERE clause
	whereRe := regexp.MustCompile(`(?i)WHERE\s+(.+?)(?:\sGROUP|\sORDER|\sLIMIT|$)`)
	whereMatch := whereRe.FindStringSubmatch(query)
	if whereMatch != nil {
		q.Where = strings.TrimSpace(whereMatch[1])
	}

	// LIMIT clause
	limitRe := regexp.MustCompile(`(?i)LIMIT\s+(\d+)`)
	limitMatch := limitRe.FindStringSubmatch(upperQuery)
	if limitMatch != nil {
		if n, err := strconv.Atoi(limitMatch[1]); err == nil {
			q.Limit = n
		}
	}

	return q, nil
}

func filterRows(rows []map[string]interface{}, whereClause string) []map[string]interface{} {
	var result []map[string]interface{}

	for _, row := range rows {
		if evaluateCondition(row, whereClause) {
			result = append(result, row)
		}
	}

	return result
}

func evaluateCondition(row map[string]interface{}, condition string) bool {
	// Handle multiple conditions joined by AND/OR
	if strings.Contains(strings.ToUpper(condition), " AND ") {
		parts := strings.Split(condition, " AND ")
		for _, part := range parts {
			if !evaluateSingleCondition(row, strings.TrimSpace(part)) {
				return false
			}
		}
		return true
	}

	if strings.Contains(strings.ToUpper(condition), " OR ") {
		parts := strings.Split(condition, " OR ")
		for _, part := range parts {
			if evaluateSingleCondition(row, strings.TrimSpace(part)) {
				return true
			}
		}
		return false
	}

	return evaluateSingleCondition(row, condition)
}

func evaluateSingleCondition(row map[string]interface{}, condition string) bool {
	// Operators in order of precedence
	operators := []string{" >= ", " <= ", " <> ", "!=", " = ", " > ", " < "}

	for _, op := range operators {
		if idx := strings.Index(condition, op); idx >= 0 {
			colName := strings.TrimSpace(condition[:idx])
			compareVal := strings.TrimSpace(condition[idx+len(op):])

			// Get column value
			colVal, ok := row[colName]
			if !ok {
				return false
			}

			// Compare
			return compareValues(colVal, compareVal, op)
		}
	}

	return true
}

func compareValues(val interface{}, compareStr string, op string) bool {
	// Remove quotes from compareStr
	compareStr = strings.Trim(compareStr, "\"'")

	valStr := fmt.Sprintf("%v", val)

	switch op {
	case " = ":
		return valStr == compareStr
	case " > ":
		return compareNumeric(valStr, compareStr, func(a, b float64) bool { return a > b })
	case " < ":
		return compareNumeric(valStr, compareStr, func(a, b float64) bool { return a < b })
	case " >= ":
		return compareNumeric(valStr, compareStr, func(a, b float64) bool { return a >= b })
	case " <= ":
		return compareNumeric(valStr, compareStr, func(a, b float64) bool { return a <= b })
	case " <> ", "!=":
		return valStr != compareStr
	}

	return true
}

func compareNumeric(a, b string, cmp func(float64, float64) bool) bool {
	var aVal, bVal float64
	_, errA := fmt.Sscanf(a, "%f", &aVal)
	_, errB := fmt.Sscanf(b, "%f", &bVal)

	if errA != nil || errB != nil {
		return false
	}

	return cmp(aVal, bVal)
}

func projectRows(rows []map[string]interface{}, columns []string) []map[string]interface{} {
	var result []map[string]interface{}

	for _, row := range rows {
		projected := make(map[string]interface{})
		for _, col := range columns {
			col = strings.TrimSpace(col)
			if v, ok := row[col]; ok {
				projected[col] = v
			}
		}
