	}

	if schemaOnly {
		if len(allData) == 1 {
			return allData[0], nil
		}
		return allData, nil
	}

	if query == "" {
		if len(allData) == 1 {
			return allData[0], nil
		}
		return allData, nil
	}

	// Execute SQL query
	result, err := executeSQLQuery(allData, query)
	if err != nil {
		return nil, err
	}
	return result, nil
