	flag.Parse()

	if *versionPtr {
		fmt.Printf("dsq %s\n", VERSION)
		return
	}

	if *helpPtr || *helpLongPtr {
		printHelp()
		return
	}

	pretty := *prettyPtr || *prettyLongPtr
	cache := *cachePtr || *cacheLongPtr
	_ = *interactivePtr
	_ = *interactiveLongPtr

	args := flag.Args()

	// Handle help
	if len(args) == 0 && !cache && *formatPtr == "" && *queryFilePtr == "" && !*schemaPtr {
		printHelp()
		return
	}

	if *formatPtr != "" {
		// Reading from stdin
		fmt.Fprintf(os.Stderr, "Cache invalid, re-import required.\n")
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error reading stdin: %v\n", err)
			os.Exit(1)
		}

		query := ""
		if len(args) > 0 {
			query = args[0]
		}
		if *queryFilePtr != "" {
			qdata, err := os.ReadFile(*queryFilePtr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error reading query file: %v\n", err)
				os.Exit(1)
			}
			query = string(qdata)
		}

		result, err := processData(string(data), *formatPtr, []string{}, query, *schemaPtr, cache)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		if *schemaPtr {
			printSchema(result)
		} else if pretty {
			printPretty(result)
		} else {
			printJSON(result)
		}
	} else if len(args) > 0 {
		// Files provided
		var files []string
		var query string

		// Separate files from query
		// Files are things that exist on the filesystem
		// Query is the rest
		for i, arg := range args {
			if _, err := os.Stat(arg); err == nil {
				files = append(files, arg)
			} else {
				// Rest are query parts
				query = strings.Join(args[i:], " ")
				break
			}
		}

		// If no query found in args and no queryfile, return all rows
		if query == "" && *queryFilePtr == "" {
			// Check if we have non-file args
			if len(args) > len(files) {
				query = args[len(files)]
			}
		}

		if *queryFilePtr != "" {
			qdata, err := os.ReadFile(*queryFilePtr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error reading query file: %v\n", err)
				os.Exit(1)
			}
			query = string(qdata)
		}

		result, err := processData("", "", files, query, *schemaPtr, cache)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		if *schemaPtr {
			printSchema(result)
		} else if pretty {
			printPretty(result)
		} else {
			printJSON(result)
		}
	}
}

func printHelp() {
	fmt.Printf(`dsq (Version %s) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq
`, VERSION)
}

func printJSON(data interface{}) {
	b, _ := json.Marshal(data)
	fmt.Printf("%s\n", string(b))
}

func printSchema(data interface{}) {
	// For now, just convert to JSON
	schema := inferSchema(data)
	b, _ := json.MarshalIndent(schema, "", "  ")
	fmt.Printf("%s\n", string(b))
}

func printPretty(data interface{}) {
	// Convert to table format
	rows := []map[string]interface{}{}
	if arrData, ok := data.([]interface{}); ok {
		for _, item := range arrData {
			if m, ok := item.(map[string]interface{}); ok {
				rows = append(rows, m)
			}
		}
	} else if arrData, ok := data.([]map[string]interface{}); ok {
		rows = arrData
	}

	if len(rows) == 0 {
		fmt.Println("(0 rows)")
		return
	}

	// Get all column names
	colNames := []string{}
	colMap := make(map[string]bool)
	for _, row := range rows {
		for key := range row {
			if !colMap[key] {
				colNames = append(colNames, key)
				colMap[key] = true
			}
		}
	}

	// Print header
	fmt.Print("+")
	for _, col := range colNames {
		fmt.Print(strings.Repeat("-", len(col)+2))
		fmt.Print("+")
	}
	fmt.Println()

	fmt.Print("|")
	for _, col := range colNames {
		fmt.Printf(" %s |", col)
	}
	fmt.Println()

	fmt.Print("+")
	for _, col := range colNames {
		fmt.Print(strings.Repeat("-", len(col)+2))
		fmt.Print("+")
	}
	fmt.Println()

	// Print rows
	for _, row := range rows {
		fmt.Print("|")
		for _, col := range colNames {
			val := ""
			if v, ok := row[col]; ok {
				val = fmt.Sprintf("%v", v)
			}
			fmt.Printf(" %s |", val)
		}
		fmt.Println()
	}

	fmt.Print("+")
	for _, col := range colNames {
		fmt.Print(strings.Repeat("-", len(col)+2))
		fmt.Print("+")
	}
	fmt.Println()

	fmt.Printf("(%d rows)\n", len(rows))
}

func inferSchema(data interface{}) interface{} {
	// Simple schema inference
	schema := map[string]interface{}{
		"kind": "array",
		"array": map[string]interface{}{
			"kind": "object",
			"object": map[string]interface{}{},
		},
	}
	return schema
}

func processData(content string, format string, files []string, query string, schemaOnly bool, cache bool) (interface{}, error) {
	// If we have content, it's from stdin
	if content != "" {
		rows, err := parseContent(content, format, "")
		if err != nil {
			return nil, err
		}

		if schemaOnly {
			return rows, nil
		}

		if query == "" {
			return rows, nil
		}

		// Execute SQL query
		result, err := executeSQLQuery([]interface{}{rows}, query)
		if err != nil {
			return nil, err
		}
		return result, nil
	}

	// Otherwise, process files
	if len(files) == 0 {
		return nil, fmt.Errorf("no input provided")
	}

	allData := []interface{}{}
	for _, file := range files {
		content, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}

		format := detectFormat(file)
		rows, err := parseContent(string(content), format, file)
		if err != nil {
			return nil, err
		}
		allData = append(allData, rows)
	}

	if schemaOnly {
		if len(allData) == 1 {
			return allData[0], nil
		}
		return allData, nil
	}

	if query == "" {
		if len(allData) == 1 {
			return allData[0], nil
		}
		return allData, nil
	}

	// Execute SQL query
	result, err := executeSQLQuery(allData, query)
	if err != nil {
		return nil, err
	}
	return result, nil
}

func detectFormat(filename string) string {
	ext := strings.ToLower(filepath.Ext(filename))
	switch ext {
	case ".csv":
		return "csv"
	case ".tsv":
		return "tsv"
	case ".json":
		return "json"
	case ".jsonl", ".ndjson":
		return "ndjson"
	case ".parquet":
		return "parquet"
	case ".xlsx":
		return "xlsx"
	case ".xls":
		return "xls"
	case ".ods":
		return "ods"
	case ".avro":
		return "avro"
	case ".orc":
		return "orc"
	case ".logfmt":
		return "logfmt"
	default:
		return "json"
	}
}

func parseContent(content string, format string, filename string) ([]map[string]interface{}, error) {
	switch format {
	case "csv":
		return parseCSV(content, ",")
	case "tsv":
		return parseCSV(content, "\t")
	case "json":
		return parseJSON(content)
	case "ndjson":
		return parseNDJSON(content)
	case "logfmt":
		return parseLogfmt(content)
	case "parquet":
		if filename != "" {
			return parseParquet([]byte(content), filename)
		}
		return nil, fmt.Errorf("parquet format not available for stdin")
	case "xlsx":
		if filename != "" {
			return parseXLSX([]byte(content), filename)
		}
		return nil, fmt.Errorf("xlsx format not available for stdin")
	case "xls":
		if filename != "" {
			return parseXLS([]byte(content), filename)
		}
		return nil, fmt.Errorf("xls format not available for stdin")
	case "ods":
		if filename != "" {
			return parseODS([]byte(content), filename)
		}
		return nil, fmt.Errorf("ods format not available for stdin")
	case "avro":
		if filename != "" {
			return parseAvro([]byte(content), filename)
		}
		return nil, fmt.Errorf("avro format not available for stdin")
	case "orc":
		if filename != "" {
			return parseORC([]byte(content), filename)
		}
		return nil, fmt.Errorf("orc format not available for stdin")
	default:
		return nil, fmt.Errorf("unsupported format: %s", format)
	}
}

func parseCSV(content string, delimiter string) ([]map[string]interface{}, error) {
	r := csv.NewReader(strings.NewReader(content))
	r.Comma = rune(delimiter[0])

	records, err := r.ReadAll()
	if err != nil {
		return nil, err
	}

	if len(records) == 0 {
		return []map[string]interface{}{}, nil
	}

	headers := records[0]
	var rows []map[string]interface{}

	for _, record := range records[1:] {
		row := make(map[string]interface{})
		for i, header := range headers {
			if i < len(record) {
				row[header] = record[i]
			}
		}
		rows = append(rows, row)
	}

	return rows, nil
}

func parseJSON(content string) ([]map[string]interface{}, error) {
	var data interface{}
	err := json.Unmarshal([]byte(content), &data)
	if err != nil {
		return nil, err
	}

	if arr, ok := data.([]interface{}); ok {
		var rows []map[string]interface{}
		for _, item := range arr {
			if m, ok := item.(map[string]interface{}); ok {
				rows = append(rows, m)
			}
		}
		return rows, nil
	}

	return nil, fmt.Errorf("JSON must be an array")
}

func parseNDJSON(content string) ([]map[string]interface{}, error) {
	var rows []map[string]interface{}
	scanner := bufio.NewScanner(strings.NewReader(content))

	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}
		var m map[string]interface{}
		err := json.Unmarshal([]byte(line), &m)
		if err != nil {
			return nil, err
		}
		rows = append(rows, m)
	}

	return rows, nil
}

func parseLogfmt(content string) ([]map[string]interface{}, error) {
	var rows []map[string]interface{}
	scanner := bufio.NewScanner(strings.NewReader(content))

	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}
		m := parseLogfmtLine(line)
		rows = append(rows, m)
	}

	return rows, nil
}

func parseLogfmtLine(line string) map[string]interface{} {
	row := make(map[string]interface{})
	i := 0
	for i < len(line) {
		// Skip whitespace
		for i < len(line) && line[i] == ' ' {
			i++
		}
		if i >= len(line) {
			break
		}

		// Find key
		keyStart := i
		for i < len(line) && line[i] != '=' && line[i] != ' ' {
			i++
		}
		if i >= len(line) || line[i] != '=' {
			break
		}
		key := line[keyStart:i]

		// Skip equals
		i++

		// Find value
		var value string
		if i < len(line) && line[i] == '"' {
			// Quoted value
			i++
			valueStart := i
			for i < len(line) && line[i] != '"' {
				if line[i] == '\\' && i+1 < len(line) {
					i++
				}
				i++
			}
			value = line[valueStart:i]
			if i < len(line) {
				i++ // Skip closing quote
			}
		} else {
			// Unquoted value
			valueStart := i
			for i < len(line) && line[i] != ' ' {
				i++
			}
			value = line[valueStart:i]
		}

		// Parse value
		if v, err := tryParseValue(value); err == nil {
			row[key] = v
		} else {
			row[key] = value
		}
	}

	return row
}

func tryParseValue(value string) (interface{}, error) {
	// Try boolean
	if value == "true" {
		return true, nil
	}
	if value == "false" {
		return false, nil
	}

	// Try number
	if strings.Contains(value, ".") {
		var f float64
		_, err := fmt.Sscanf(value, "%f", &f)
		if err == nil {
			return f, nil
		}
	} else {
		var i int64
		_, err := fmt.Sscanf(value, "%d", &i)
		if err == nil {
			return i, nil
		}
	}

	return nil, fmt.Errorf("not a special value")
}
